column1:
Variables: {PRICE} - regular price; {BR} - new line;{SAVE_PERCENT} - save percent;
{SAVE_AMOUNT} - save amount; {SPECIAL_PRICE} - special price; {ATTR:code} - attribute value, e.g.
{ATTR:color};{SPDL} - days left for special price; {SPHL} - hours left for special price;
{NEW_FOR} - days ago the product was added; {SKU} - product SKU;
{STOCK} - product qty (for product view page).

column2:
Variables : {PRICE} - prix normal ; {BR} - saut de ligne ; {SAVE_PERCENT} - pourcentage d’économie ;
{SAVE_AMOUNT} - montant économisé ; {SPECIAL_PRICE} - prix spécial ; {ATTR:code} - valeur d’attribut, par ex.
{ATTR:color} ; {SPDL} - jours restants du prix spécial ; {SPHL} - heures restantes du prix spécial ;
{NEW_FOR} - nombre de jours depuis l’ajout du produit ; {SKU} - SKU du produit ;
{STOCK} - quantité du produit (page produit).

